import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第二十六章","description":"《正易心法》第二十六章——反对正如，甲子乙丑：凡物之气有本有余，余气为阴、本为阳；坤为乾之余气、蒙为屯之余气，故卦序相次皆余气，自然之理。","frontmatter":{"title":"正易心法·第二十六章","description":"《正易心法》第二十六章——反对正如，甲子乙丑：凡物之气有本有余，余气为阴、本为阳；坤为乾之余气、蒙为屯之余气，故卦序相次皆余气，自然之理。","category":"guide","aliases":["正易心法第二十六章","有本有余气序自然","余气"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-26.md","filePath":"yijing/zheng-yi-xin-fa/chapter-26.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-26.md"},x=p({...c,setup(u){const i=[{id:"z26-01",label:"一、反对正如甲子乙丑",showLabel:!0,sentences:[["反对正如，甲子乙丑。有本有余，",{text:"气序自然",glossary:"qixuZiran"},"。"]],note:["反卦与对卦的关系正是如此——就像甲子与乙丑。有本气，有余气，气的顺序是自然形成的。（**本章是第十六至十八章「反对」体系的更深一层**：前面说「反卦相邻」（结构），本章说「为什么相邻」——**因为后卦是前卦的余气**（气化）。）"]},{id:"z26-02",label:"二、本与余",showLabel:!0,sentences:[["大凡一物，其气象必有本有余。",{text:"余气",glossary:"yuqi"},"者，所以为阴也。本，其阳也。"]],note:["大体上，任何事物的气象必然有本气、有余气。余气，就是阴的来源；本气，就是阳。（**这是本章的框架**：**本＝阳＝充盛、先行**；**余＝阴＝余韵、后随**。这不是经验观察，而是「气」的运行方式：气运行到极处必然收敛，收敛处就是余气。）"]},{id:"z26-03",label:"三、十干之例",showLabel:!0,sentences:[["如",{text:"十干",glossary:"shigan"},"甲乙，乙者甲之余气也。丙丁，丁者丙之余气也。"]],note:["比如十天干中的甲乙：乙，是甲的余气；丙丁：丁，是丙的余气。（**规律很整齐**：甲丙戊庚壬这五个奇数干为「本」（阳），乙丁己辛癸这五个偶数干为「余」（阴）——**每一对都是「阳干＋它的余气」**。）"]},{id:"z26-04",label:"四、十二支之例",showLabel:!0,sentences:[["如",{text:"十二支",glossary:"shierZhi"},"子丑，丑者子之余气也。寅卯，卯者寅之余气也。"]],note:["比如十二地支中的子丑：丑，是子的余气；寅卯：卯，是寅的余气。（**地支的十二个，同样是「阳支为本、阴支为余」交替**。麻衣举天干、地支两例，是在说明「本余」不是卦序特有的规则，而是贯穿一切「气」的编号方式。）"]},{id:"z26-05",label:"五、卦之例",showLabel:!0,sentences:[["卦亦由是。坤者，乾之余气也。蒙者，屯之余气也。讼者，需之余气也。比者，师之余气也。"]],note:["卦的道理也是如此：坤，是乾的余气；蒙，是屯的余气；讼，是需的余气；比，是师的余气。（**对照卦序**：乾（一）→坤（二）、屯（三）→蒙（四）、需（五）→讼（六）、师（七）→比（八）——**每一对都是「奇数卦为本，偶数卦为余」**，而每一对恰好又是互为反卦的（屯与蒙颠倒、需与讼颠倒、师与比颠倒）。**所以「反卦相邻」与「本余相随」是同一件事。**）"]},{id:"z26-06",label:"六、相次皆余气",showLabel:!0,sentences:[["且乾而后坤，屯而后蒙，需而后讼，师而后比，虽故有其义，然其所以",{text:"相次",glossary:"xiangci"},"者，皆其余气也，自然之理耳。"]],note:["乾之后是坤、屯之后是蒙、需之后是讼、师之后是比——虽然这些相邻的卦之间本来就有各自的义理，但它们之所以紧邻排列，都是因为余气的关系，这是自然之理。（**麻衣的分寸**：他并不否定《序卦传》讲的义理，只说「**虽故有其义，然其所以相次者，皆其余气也**」——义理是「有」，余气是「所以然」。**义理说的是「它们有什么关系」，余气说的是「它们为什么挨着」。**）"]},{id:"z26-07",label:"七、学者不悟",showLabel:!0,sentences:[["学者不悟，谓圣人",{text:"固以次之",glossary:"guyiCizhi"},"，是未知",{text:"反对关键之键",glossary:"fanduiGuajian"},"也，失之远矣。"]],note:["学者不能领悟，以为是圣人本来就这样排列的，这是不知道反对关键的关键所在，偏差太远了。（**「固以次之」与「气序自然」正好相反**：一个说「圣人安排的」，一个说「气自己走的」。**「失之远矣」是麻衣极重的批评用语**——不是「理解不深」，是「方向完全错了」。）"]}],l=[{id:"qixuZiran",term:"气序自然",pinyin:"qì xù zì rán",meaning:"气的顺序是自然形成的。卦序不是圣人人为安排，而是气的自然流行。"},{id:"yuqi",term:"余气",pinyin:"yú qì",meaning:"本气散尽后残留的气。阴为阳之余气；偶数干支为奇数干支的余气。"},{id:"shigan",term:"十干",pinyin:"shí gān",meaning:"十天干：甲乙丙丁戊己庚辛壬癸。奇数干为阳（本），偶数干为阴（余）。"},{id:"shierZhi",term:"十二支",pinyin:"shí èr zhī",meaning:"十二地支：子丑寅卯辰巳午未申酉戌亥。奇数支为阳（本），偶数支为阴（余）。"},{id:"xiangci",term:"相次",pinyin:"xiāng cì",meaning:"相互紧邻排列。次是次序，紧接着。"},{id:"guyiCizhi",term:"固以次之",pinyin:"gù yǐ cì zhī",meaning:"本来就是这样排列的。固是本来、原本。"},{id:"fanduiGuajian",term:"反对关键之键",pinyin:"fǎn duì guān jiàn",meaning:"反对义的关键所在。麻衣强调这是理解卦序的核心钥匙。「键」字两见，极言其要。"}];return(b,n)=>{const o=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第二十六章" tabindex="-1">正易心法·第二十六章 <a class="header-anchor" href="#正易心法·第二十六章" aria-label="Permalink to &quot;正易心法·第二十六章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章的核心命题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卦序不是圣人的主观安排</span></span>
<span class="line"><span>而是「本余之气」的自然流行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>论证路径：</span></span>
<span class="line"><span>  天干（甲乙、丙丁）→ 奇阳为本，偶阴为余</span></span>
<span class="line"><span>  地支（子丑、寅卯）→ 奇阳为本，偶阴为余</span></span>
<span class="line"><span>  卦序（乾坤、屯蒙）→ 奇卦为本，偶卦为余</span></span></code></pre></div><p><strong>结论</strong>：<strong>反卦相邻 = 本余相随 = 气序自然。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>本气与余气的普遍结构</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天干的本余关系：</span></span>
<span class="line"><span>  甲（本）→ 乙（余）    丙（本）→ 丁（余）……</span></span>
<span class="line"><span>  奇数干 = 阳干（本）   偶数干 = 阴干（余）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>地支的本余关系：</span></span>
<span class="line"><span>  子（本）→ 丑（余）    寅（本）→ 卯（余）……</span></span>
<span class="line"><span>  奇数支 = 阳支（本）   偶数支 = 阴支（余）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>统一规律：</span></span>
<span class="line"><span>  阳 → 阴      本 → 余      先 → 后      充盛 → 延续</span></span></code></pre></div><p><strong>卦序的本余关系</strong>：</p><table tabindex="0"><thead><tr><th>序号</th><th>卦</th><th>角色</th><th>与下一卦的关系</th></tr></thead><tbody><tr><td>1</td><td>乾</td><td>本</td><td>坤是乾之余气</td></tr><tr><td>2</td><td>坤</td><td>余</td><td>—</td></tr><tr><td>3</td><td>屯</td><td>本</td><td>蒙是屯之余气</td></tr><tr><td>4</td><td>蒙</td><td>余</td><td>—</td></tr><tr><td>5</td><td>需</td><td>本</td><td>讼是需之余气</td></tr><tr><td>6</td><td>讼</td><td>余</td><td>—</td></tr><tr><td>7</td><td>师</td><td>本</td><td>比是师之余气</td></tr><tr><td>8</td><td>比</td><td>余</td><td>—</td></tr></tbody></table><p><strong>注意</strong>：乾与坤互为错卦，屯与蒙、需与讼、师与比皆互为反卦（综卦）——<strong>所以「反卦相邻」与「本余相随」是同一件事。</strong></p><p><strong>「余气」的深层含义</strong>——余气不是「残渣」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本气：充盛、饱满、向外扩张（阳）→ 运行至极</span></span>
<span class="line"><span>余气：收敛、延续、向内归藏（阴）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>类比：太阳（本）→ 月亮（余）；春夏（本）→ 秋冬（余）；呼（本）→ 吸（余）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>余气不是「剩余」，而是「延续」：</span></span>
<span class="line"><span>  甲气运行 → 未散尽 → 延续为乙</span></span>
<span class="line"><span>  乾气运行 → 未散尽 → 延续为坤</span></span>
<span class="line"><span>  = 阴不是独立存在的，阴是阳运行之后的自然状态</span></span>
<span class="line"><span>  = 阴阳不是对立的两极，而是同一气的两个阶段</span></span></code></pre></div><p><strong>这直接回应了第二十章「乾坤真体」</strong>：坤不只是「乾的对立面」，而是<strong>乾气运行之后的余气状态</strong>——坤从乾来，不离乾，真体始终是一气。</p><p><strong>「反对关键之键」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>反对（第十六至十八章）告诉你「什么」——反卦相邻（结构层面）</span></span>
<span class="line"><span>余气（第二十六章）告诉你「为什么」——后卦是前卦的余气（气化层面）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>只知反对，不知余气：知其然，不知其所以然</span></span>
<span class="line"><span>既知反对，又知余气：真正理解卦序的自然之理</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把「本／余」这对词记住：<strong>本＝阳＝先，余＝阴＝后</strong>；</li><li>再看天干、地支、卦序三处是不是同一个规律；</li><li>最后读「反对关键之键」——<strong>「键」字两见，是本章的分量所在。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>有本有余</strong>：凡物之气必有本、有余。</li><li><strong>余气为阴</strong>：阴是阳运行之后的延续状态。</li><li><strong>十干十二支</strong>：奇为本、偶为余。</li><li><strong>卦亦由是</strong>：坤为乾之余气，蒙为屯之余气。</li><li><strong>相次皆余气</strong>：卦序相邻非人为安排。</li><li><strong>反对关键之键</strong>：余气是反对义的根源。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(o,{colophon:"有本有余 · 气序自然 · 十干十二支 · 反对关键之键",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十六章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"本与余",pinyin:["běn","yú"],meaning:"本＝阳＝充盛、先行；余＝阴＝余韵、后随。凡物之气必有本有余。"},{term:"余气",pinyin:["yú","qì"],meaning:"不是「残渣」，而是「延续」：甲气未散尽则延续为乙，乾气未散尽则延续为坤。"},{term:"气序自然",pinyin:["qì","xù"],meaning:"卦序不是圣人人为安排，而是本余之气的自然流行——反卦相邻即本余相随。"},{term:"固以次之",pinyin:["gù","yǐ"],meaning:"「以为圣人本来就是这样排列的」——麻衣批评学者不悟气序自然之理。"},{term:"反对关键之键",pinyin:["fǎn","duì"],meaning:"反对义的关键所在。「键」字两见，极言其要：余气是反对义的根源。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章的核心命题：<strong>卦序不是圣人的主观安排，而是「本余之气」的自然流行。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天干：奇阳为本，偶阴为余</span></span>
<span class="line"><span>地支：奇阳为本，偶阴为余</span></span>
<span class="line"><span>卦序：奇卦为本，偶卦为余（坤为乾之余气……）</span></span></code></pre></div><p><strong>结论：反卦相邻 = 本余相随 = 气序自然。</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「余气」的哲学意义</strong>——余气不是「剩余」，而是「延续」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>甲气运行 → 未散尽 → 延续为乙</span></span>
<span class="line"><span>乾气运行 → 未散尽 → 延续为坤</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这意味着：阴不是独立存在的</span></span>
<span class="line"><span>          阴是阳运行之后的自然状态</span></span>
<span class="line"><span>          = 阴阳不是对立的两极，而是同一气的两个阶段</span></span></code></pre></div><p><strong>这直接回应第二十章「乾坤真体」</strong>：坤不只是乾的对立面，而是乾气运行之后的余气状态——<strong>坤从乾来，不离乾，真体始终是一气。</strong></p><p><strong>「反对关键之键」</strong>：</p><table tabindex="0"><thead><tr><th>层</th><th>内容</th></tr></thead><tbody><tr><td>反对（第十六至十八章）</td><td>告诉你「什么」——反卦相邻（结构）</td></tr><tr><td>余气（第二十六章）</td><td>告诉你「为什么」——后卦是前卦的余气（气化）</td></tr></tbody></table><p><strong>麻衣的分寸</strong>：他并不否定《序卦传》讲的义理，只说「<strong>虽故有其义，然其所以相次者，皆其余气也</strong>」——<strong>义理说的是「它们有什么关系」，余气说的是「它们为什么挨着」。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>记住「本／余」这对词：<strong>本＝阳＝先，余＝阴＝后</strong>；</li><li>拿天干、地支、卦序三处各看一遍，<strong>看是不是同一个规律</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>如果「阴是阳的余气」，那么阴阳还平等吗？</strong> 我的看法：<strong>麻衣的「余气说」确实偏向「阳主阴从」一侧</strong>，但要注意他给「余」留了尊严——<strong>余不是残余，是延续；不是低一级，是下一步。</strong> 用他第二十一章的话说：「阴阳一气」——<strong>如果阴阳本是一气的两个状态，那么「谁先谁后」只是气的运行次序，不是「谁高谁低」。</strong> 真正的不平等，是<strong>把「余」当成了「废」</strong>——那是读者加上去的，不是麻衣说的。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>反卦与对卦的关系正是如此——就像甲子与乙丑。有本气，有余气，气的顺序是自然形成的。</p><p>大体上，任何事物的气象必然有本气、有余气。余气，就是阴的来源；本气，就是阳。</p><p>比如十天干中的甲乙：乙，是甲的余气；丙丁：丁，是丙的余气。比如十二地支中的子丑：丑，是子的余气；寅卯：卯，是寅的余气。</p><p>卦的道理也是如此：坤，是乾的余气；蒙，是屯的余气；讼，是需的余气；比，是师的余气。</p><p>乾之后是坤、屯之后是蒙、需之后是讼、师之后是比——虽然这些相邻的卦之间本来就有各自的义理，但它们之所以紧邻排列，都是因为余气的关系，这是自然之理。</p><p>学者不能领悟，以为是圣人本来就这样排列的，这是不知道反对关键的关键所在，偏差太远了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十六章回答了第十六章留下的问题——<strong>反卦为什么总是相邻？因为后一卦是前一卦的「余气」。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「本与余」</strong>——这对词是本章的钥匙。<strong>本气走到极处，余气自然生出。</strong> 不是「两件事先后发生」，是<strong>一件事的两种状态。</strong></li><li><strong>天干地支与卦序三处同一个规律</strong>——奇为本、偶为余。<strong>麻衣不是在类比，是在说同一个结构在三个系统里显形。</strong></li><li><strong>「余气」不是残渣</strong>——这一点要注意。<strong>余气不是「剩下来的」，是「延续下来的」</strong>：甲气未散尽，延续为乙。<strong>诗人说「余音绕梁」，「余」是最好听的那部分。</strong></li><li><strong>「虽故有其义，然其所以相次者」</strong>——麻衣的分寸很准。<strong>他不否定义理，只说义理是「有」，余气是「所以然」。</strong> 一手不推翻旧说，一手补上更深的一层。</li><li><strong>「反对关键之键」</strong>——「键」字用了两次（另一处在别处作「关键」），<strong>极言其要</strong>。<strong>反对是钥匙，余气是钥匙上的齿。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>如果阴只是阳的余气，那么阴阳真平等吗？</strong> 我的看法：<strong>麻衣的「余气说」确实偏「阳主阴从」一侧</strong>，但他给「余」留了尊严——<strong>余不是残余，是延续。</strong> 用他第二十一章的话说：「阴阳一气」。<strong>真正的不平等，是把「余」当成了「废」——那是读者加上去的。</strong> 而在麻衣这里，<strong>坤是乾的余气，所以坤卑而不下；正如夜是昼的余气，但夜有夜的好。</strong> 这个偏向我不打算替他抹平——<strong>把它看清楚，比假装它不存在更有用。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-16">第十六章 · 卦有反对</a> — 反对密意（本章揭示其根源）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-20">第二十章 · 唯乾与坤</a> — 「乾坤真体」（坤为乾之余气，真体始终一气）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-21">第二十一章 · 乾坤杂气</a> — 「阴阳一气」（本章的「余气」是其进一步展开）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-23">第二十三章 · 舛讹为多</a> — 卦序之误（本章给出卦序的所以然）</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 义理相因的卦序（本章说「相次者皆余气」）</li></ul>`,27))])}}});export{m as __pageData,x as default};
